<?php
declare(strict_types=1);
// Run after operational_completion.php in the same fresh synthetic schema.
require dirname(__DIR__).'/app/Database.php';
require dirname(__DIR__).'/app/FinancialService.php';
require dirname(__DIR__).'/app/FinancialState.php';
$c=require dirname(__DIR__).'/config/settings.php';
if($c['environment']!=='local'||$c['db']['host']!=='127.0.0.1'||!preg_match('/\Acentro_auth_[a-z0-9_]+\z/D',$c['db']['name']))throw new RuntimeException('Synthetic schema required');
$p=Centro\Database::connection($c['db']);$s=new Centro\FinancialService($p);$checks=[];
$check=function(string $name,bool $ok)use(&$checks){$checks[]=['check'=>$name,'passed'=>$ok];};
$q=function(string $sql,array $args=[])use($p){$q=$p->prepare($sql);$q->execute($args);return $q;};
$scalar=fn(string $sql,array $args=[])=>$q($sql,$args)->fetchColumn();
$run=fn(string $op,array $cmd)=>$s->execute('pruebas',str_pad('follow_'.$op,20,'x'),1,$cmd);
$version=fn(string $table,string $id)=>(int)$scalar("SELECT row_version FROM $table WHERE environment_id='pruebas' AND id=?",[$id]);
$snapshot=function()use($q){$state=[];foreach(['fin_movements','fin_sales','fin_sale_lines','fin_expenses','fin_sale_revisions','fin_expense_revisions','fin_sale_line_revisions','fin_entity_metadata','fin_operation_receipts','fin_audit','customers','subscriptions','subscription_events','fin_subscription_evidence'] as $table)$state[$table]=$q("SELECT * FROM $table ORDER BY 1,2,3")->fetchAll();return $state;};
$reject=function(string $name,string $reason,callable $fn)use($check,$snapshot,$p){$before=$snapshot();try{$fn();$check($name,false);}catch(Centro\BusinessError $e){$check($name,$e->reason===$reason&&!$p->inTransaction()&&$snapshot()===$before);}};
$rows=$q('SELECT version,checksum FROM schema_migrations')->fetchAll();
$check('all applied migrations have immutable checksums',count($rows)===count(glob(dirname(__DIR__).'/database/migrations/*.sql'))&&count(array_filter($rows,fn($r)=>hash_equals(hash_file('sha256',dirname(__DIR__).'/database/migrations/'.$r['version'].'.sql'),$r['checksum'])))===count($rows));
$balance=$scalar("SELECT SUM(CASE direction WHEN 'in' THEN amount ELSE -amount END) FROM fin_movements WHERE account_id='cash'");
$reject('invalid treasury note rolls back every effect','invalid_note',fn()=>$run('bad_note',['kind'=>'capital_contribution','amount'=>'1.00','currency'=>'USD','account_id'=>'cash','date'=>'2026-10-21','confirmed'=>true,'note'=>['invalid']]));
// An initial payment has its own explicit date; expense recognition keeps its date.
$cmd=['kind'=>'expense_register','expense_id'=>'dated_exp','amount'=>'9.00','currency'=>'USD','date'=>'2026-01-10','payment_date'=>'2026-02-05','settle_now'=>true,'confirmed'=>true,'account_id'=>'cash','record'=>['concept'=>'Synthetic dated payment','nature'=>'gasto','frequency'=>'mensual','alloc'=>['mode'=>'general','targets'=>[]]]];
$r=$run('dated_exp',$cmd);$replay=$run('dated_exp',$cmd);
$check('initial payment date is independent from expense date',$scalar("SELECT incurred_on FROM fin_expenses WHERE id='dated_exp'")==='2026-01-10'&&$scalar("SELECT movement_on FROM fin_movements WHERE expense_id='dated_exp'")==='2026-02-05');
$check('dated payment replays exactly once',$replay['replayed']&&$scalar("SELECT COUNT(*) FROM fin_movements WHERE expense_id='dated_exp'")===1);
$run('recurring_exp',['kind'=>'expense_register','expense_id'=>'next_exp','amount'=>'9.00','currency'=>'USD','date'=>'2026-02-10','record'=>['concept'=>'Synthetic dated payment','frequency'=>'mensual','dueDate'=>'2026-02-15']]);
$check('recurring period creates only a pending expense',$scalar("SELECT status FROM fin_expenses WHERE id='next_exp'")==='pendiente'&&$scalar("SELECT COUNT(*) FROM fin_movements WHERE expense_id='next_exp'")===0);
$reject('bad allocation rolls back expense and receipt','allocation_reference_invalid',fn()=>$run('bad_alloc',['kind'=>'expense_register','expense_id'=>'bad_alloc','amount'=>'1.00','currency'=>'USD','date'=>'2026-10-21','record'=>['alloc'=>['mode'=>'single','targets'=>[['type'=>'project','id'=>'missing']]]]]));
$paidMoves=$scalar("SELECT COUNT(*) FROM fin_movements WHERE sale_id='first'");$total=$scalar("SELECT total FROM fin_sales WHERE id='first'");
$run('delivery',['kind'=>'sale_edit','sale_id'=>'first','expected_version'=>$version('fin_sales','first'),'record'=>['delivery'=>'pendiente','notes'=>'Synthetic delivery note']]);
$check('collected sale details never mutate cash or totals',$scalar("SELECT COUNT(*) FROM fin_movements WHERE sale_id='first'")===$paidMoves&&$scalar("SELECT total FROM fin_sales WHERE id='first'")===$total);
$reject('invalid metadata rolls back revision and version','invalid_record_field',fn()=>$run('bad_metadata',['kind'=>'sale_edit','sale_id'=>'first','expected_version'=>$version('fin_sales','first'),'record'=>['concept'=>['bad']]]));
$reject('cross-reference in metadata is validated','metadata_reference_invalid',fn()=>$run('bad_reference',['kind'=>'sale_edit','sale_id'=>'first','expected_version'=>$version('fin_sales','first'),'record'=>['projectId'=>'missing']]));
$reject('financial edit cannot rewrite a collected sale','sale_has_collections',fn()=>$run('paid_edit',['kind'=>'sale_edit','sale_id'=>'first','expected_version'=>$version('fin_sales','first'),'amount'=>'8.00']));
$run('line_seed',['kind'=>'sale_register','sale_id'=>'line_edit','amount'=>'10.00','currency'=>'USD','date'=>'2026-10-21','lines'=>[['quantity'=>'2','unit_price'=>'5.00','line_total'=>'10.00','description'=>'Before']]]);
$line=['quantity'=>'3','unit_price'=>'4.00','line_total'=>'12.00','description'=>'After'];
$r=$run('line_edit',['kind'=>'sale_edit','sale_id'=>'line_edit','expected_version'=>1,'amount'=>'12.00','lines'=>[$line],'record'=>['concept'=>'Revised synthetic line']]);
$check('complex line edit retains previous exact line revision',$scalar("SELECT total FROM fin_sales WHERE id='line_edit'")==='12.00'&&json_decode($scalar("SELECT lines_json FROM fin_sale_line_revisions WHERE sale_id='line_edit'"),true)[0]['line_total']==='10.00');
$reject('line total mismatch rolls back totals and history','sale_lines_total_mismatch',fn()=>$run('line_bad',['kind'=>'sale_edit','sale_id'=>'line_edit','expected_version'=>2,'amount'=>'13.00','lines'=>[$line]]));
$q("INSERT INTO suppliers(environment_id,id,name,kind,url,contact,tax_id,notes) VALUES('pruebas','supplier','Synthetic supplier','','','','','')");
$r=$run('expense_details',['kind'=>'expense_edit','expense_id'=>'exp','expected_version'=>$version('fin_expenses','exp'),'amount'=>'16.00','date'=>'2026-02-01','supplier_id'=>'supplier','record'=>['notes'=>'Synthetic revision']]);
$check('expense edit preserves prior details in durable receipt',$r['result']['previous_details']['date']==='2026-01-31'&&$scalar("SELECT incurred_on FROM fin_expenses WHERE id='exp'")==='2026-02-01'&&$scalar("SELECT supplier_id FROM fin_expenses WHERE id='exp'")==='supplier');
$reject('paid currency cannot be reinterpreted','expense_currency_has_payments',fn()=>$run('expense_currency',['kind'=>'expense_edit','expense_id'=>'exp','expected_version'=>$version('fin_expenses','exp'),'amount'=>'16.00','currency'=>'ARS']));
$run('unpaid_currency',['kind'=>'expense_edit','expense_id'=>'next_exp','expected_version'=>1,'amount'=>'10.00','currency'=>'ARS']);
$check('unpaid expense can explicitly change currency without cash mutation',$scalar("SELECT currency_id FROM fin_expenses WHERE id='next_exp'")==='ARS'&&$scalar("SELECT COUNT(*) FROM fin_movements WHERE expense_id='next_exp'")===0);
// Status-only changes retain historical evidence without requiring a new active price.
$q("UPDATE plan_prices SET valid_to='2026-02-11' WHERE id='price'");
$r=$run('expired_price_pause',['kind'=>'subscription_status','subscription_id'=>'sub','event'=>'pausa','date'=>'2026-02-12','expected_version'=>6]);
$check('suspension works after the historical price expires',$r['result']['status']==='pausada'&&$r['result']['next_renewal']==='2026-03-10');
$q("INSERT INTO plans(environment_id,id,project_id,name,status,trial_days) VALUES('pruebas','plan_new','project','New monthly','activa',7)");
$q("INSERT INTO plan_prices(environment_id,id,plan_id,valid_from,price,currency_id,period,provenance) VALUES('pruebas','price_new','plan_new','2026-01-01',15,'USD','mensual','known')");
$new=['kind'=>'subscription_register','subscription_id'=>'inline_sub','plan_id'=>'plan_new','customer_id'=>'inline_customer','date'=>'2026-10-21','trial'=>true,'expected_version'=>0,'price_snapshot_id'=>'price_new','customer'=>['id'=>'inline_customer','name'=>'Synthetic inline client','email'=>'inline@example.invalid','country'=>'AR','createdAt'=>'2026-10-21','notes'=>'']];
$r=$run('inline_customer',$new);$again=$run('inline_customer',$new);
$check('inline customer and trial persist atomically exactly once',$r['result']['next_renewal']==='2026-10-28'&&$again['replayed']&&$scalar("SELECT COUNT(*) FROM customers WHERE id='inline_customer'")===1);
$check('unknown consent and origin remain NULL',$scalar("SELECT consent FROM customers WHERE id='inline_customer'")===null&&$scalar("SELECT origin FROM customers WHERE id='inline_customer'")===null);
$bad=[...$new,'subscription_id'=>'rollback_sub','customer_id'=>'rollback_customer','price_snapshot_id'=>'missing','customer'=>[...$new['customer'],'id'=>'rollback_customer','email'=>'rollback@example.invalid']];
$reject('failed subscription rolls back inline customer too','historical_price_evidence_required',fn()=>$run('inline_failure',$bad));
$q("UPDATE plans SET trial_days=NULL WHERE id='plan_new'");
$reject('unknown historical trial length is not invented','historical_trial_evidence_required',fn()=>$run('unknown_trial',[...$new,'subscription_id'=>'unknown_trial','customer_id'=>'unknown_customer','customer'=>[...$new['customer'],'id'=>'unknown_customer','email'=>'unknown@example.invalid']]));
$fs=(new Centro\FinancialState($p))->snapshot('pruebas');
$check('SQL projection restores inline customer association',count(array_filter($fs['subscriptionCustomers'],fn($x)=>$x['id']==='inline_customer'&&$x['name']==='Synthetic inline client'))===1);
$check('exact final balance changes only by explicit payment',$scalar("SELECT SUM(CASE direction WHEN 'in' THEN amount ELSE -amount END) FROM fin_movements WHERE account_id='cash'")===bcsub($balance,'9.00',2));
$check('every committed operation has one audit',$scalar('SELECT COUNT(*) FROM fin_audit')===$scalar('SELECT COUNT(*) FROM fin_operation_receipts'));
echo json_encode(['checks'=>$checks],JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT).PHP_EOL;
exit(array_filter($checks,fn($x)=>!$x['passed'])?1:0);
